using System.ComponentModel;
using Microsoft.Testing.Platform.Builder;

namespace VerificationGlue.Tests;

/// <summary>
/// The hook that the entry point generated by <c>Microsoft.Testing.Platform.MSBuild</c> calls.
/// <c>build/VerificationGlue.Tests.props</c> names it in a <c>TestingPlatformBuilderHook</c> item.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class TestingPlatformBuilderHook
{
    /// <summary>Registers the VerificationGlue.Tests framework.</summary>
    /// <param name="builder">The test application builder.</param>
    /// <param name="_">The command line arguments.</param>
    public static void AddExtensions(ITestApplicationBuilder builder, string[] _) => builder.AddVerificationGlueTests();
}

/// <summary>Registers VerificationGlue.Tests with a Microsoft.Testing.Platform application.</summary>
public static class TestApplicationBuilderExtensions
{
    /// <summary>
    /// Registers the VerificationGlue.Tests framework. A project with its own entry point calls this;
    /// the generated entry point calls it for every other project.
    /// </summary>
    /// <param name="builder">The test application builder.</param>
    public static void AddVerificationGlueTests(this ITestApplicationBuilder builder)
    {
        var trx = new TrxCapability();
        builder.RegisterTestFramework(_ => new TestFrameworkCapabilities(trx), (_, _) => new TestFramework(trx));
    }
}
